)

// TestOPFSmoke is a one-off smoke for the OpenAI Privacy Filter integration.
// It configures OPF in the test repo, drives a Vogon session whose prompt
// mentions "Alice Smith", commits to trigger condensation, then asserts the
// condensed transcript has the name replaced with [REDACTED_PERSON].
//
// Requires `opf` installed locally.
func TestOPFSmoke(t *testing.T) {
	testutil.ForEachNamedAgent(t, 3*time.Minute, []string{"vogon"}, func(t *testing.T, s *testutil.RepoState, ctx context.Context) {
		// Commit the enable artifacts so the worktree is clean.
		s.Git(t, "add", ".")
		s.Git(t, "commit", "-m", "Enable entire")

		// Inject OPF settings into the test repo.
		testutil.PatchSettings(t, s.Dir, map[string]any{
			"redaction": map[string]any{
				"openai_privacy_filter": map[string]any{
					"enabled":         true,
					"categories":      map[string]any{"private_person": true},
					"command":         "opf",
					"timeout_seconds": 120,
					"on_failure":      "warn",
				},
			},
		})

		s.Git(t, "checkout", "-b", "feature")

		// Drive Vogon with a prompt that puts "Alice Smith" into the transcript.
		prompt := "create a file at greeting.txt with content 'Hello from Alice Smith, who lives in San Francisco'"
		_, err := s.RunPrompt(t, ctx, prompt)
		require.NoError(t, err, "agent failed")

		// Commit triggers condensation — OPF should fire.
		s.Git(t, "add", ".")
		s.Git(t, "commit", "-m", "test OPF condensation")
		testutil.WaitForCheckpoint(t, s, 30*time.Second)

		checkpointID := testutil.AssertHasCheckpointTrailer(t, s.Dir, "HEAD")
		t.Logf("checkpoint id: %s", checkpointID)

		// Read back the condensed transcript via `entire explain`.
		out := entire.Explain(t, s.Dir, checkpointID)
		t.Logf("=== explain output ===\n%s\n=== end explain ===", out)

		// The literal name should be gone, replaced with the OPF token.
		if strings.Contains(out, "Alice Smith") {
			t.Errorf("FAIL: 'Alice Smith' was NOT redacted in condensed transcript")
		}
		assert.Contains(t, out, "REDACTED_PERSON", "want OPF to redact Alice Smith to [REDACTED_PERSON]")
	})
}

