package tests

import (
	"context"
	"strings"
	"testing"
	"time"

	"github.com/entireio/cli/e2e/entire"
	"github.com/entireio/cli/e2e/testutil"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// TestOPFSmoke is a one-off smoke for the OpenAI Privacy Filter integration.
// Writes a minimal Vogon transcript that contains "Alice Smith", attaches it
// (which creates a checkpoint and triggers condensation), then asserts the
// condensed transcript has the name replaced with [REDACTED_PERSON].
//
// Uses WriteSessionTranscript + attach (minimal 2-message transcript) instead
// of a live Vogon prompt, because the live-prompt path generates many leaf
// strings and per-string OPF cold-start adds up past the harness timeout.
//
// Requires `opf` installed locally.
func TestOPFSmoke(t *testing.T) {
	testutil.ForEachNamedAgent(t, 5*time.Minute, []string{"vogon"}, func(t *testing.T, s *testutil.RepoState, ctx context.Context) {
		homeDir := t.TempDir()
		extraEnv := []string{"HOME=" + homeDir}
		vogon := requireVogonAgent(t, s)

		s.Git(t, "add", ".")
		s.Git(t, "commit", "-m", "Enable entire")

		// Inject OPF settings into the test repo.
		testutil.PatchSettings(t, s.Dir, map[string]any{
			"redaction": map[string]any{
				"openai_privacy_filter": map[string]any{
					"enabled":         true,
					"categories":      map[string]any{"private_person": true},
					"command":         "opf",
					"timeout_seconds": 120,
					"on_failure":      "warn",
				},
			},
		})

		s.Git(t, "checkout", "-b", "feature")

		// Minimal transcript: 1 user message + 1 assistant message, both
		// mention "Alice Smith" so OPF has something to redact.
		sessionID := "opf-smoke-session"
		_, writeErr := vogon.WriteSessionTranscript(ctx, s.Dir, extraEnv, sessionID,
			"Help Alice Smith write a greeting",
			"Hello Alice Smith, here is your greeting.")
		require.NoError(t, writeErr, "prepare vogon session")

		// `entire attach` creates a checkpoint from the transcript on the
		// shadow branch. Then the commit below condenses to entire/checkpoints/v1
		// which runs OPF.
		out, err := entire.AttachWithEnv(s.Dir, extraEnv, sessionID, s.Agent.EntireAgent())
		require.NoError(t, err, "entire attach failed: %s", out)

		checkpointID := testutil.AssertHasCheckpointTrailer(t, s.Dir, "HEAD")
		t.Logf("checkpoint id: %s", checkpointID)

		// Read back the condensed transcript via `entire explain`.
		explainOut := entire.Explain(t, s.Dir, checkpointID)
		t.Logf("=== explain output ===\n%s\n=== end explain ===", explainOut)

		// The literal name should be gone, replaced with the OPF token.
		if strings.Contains(explainOut, "Alice Smith") {
			t.Errorf("FAIL: 'Alice Smith' was NOT redacted in condensed transcript")
		}
		assert.Contains(t, explainOut, "REDACTED_PERSON", "want OPF to redact Alice Smith to [REDACTED_PERSON]")
	})
}

