792	// JSONLBytesWithPrivacyFilter is the augmented variant of JSONLBytes.
793	func JSONLBytesWithPrivacyFilter(ctx context.Context, b []byte) (RedactedBytes, error) {
794		s := string(b)
795		redacted, err := JSONLContentWithPrivacyFilter(ctx, s)
796		if err != nil {
797			return RedactedBytes{}, err
798		}
799		if redacted == s {
800			return RedactedBytes{data: b}, nil
801		}
802		return RedactedBytes{data: []byte(redacted)}, nil
803	}
