func main() {
	redact.ConfigurePrivacyFilter(redact.OPFConfig{
		Enabled:    true,
		Categories: map[string]bool{"private_person": true},
		Command:    "opf",
		Timeout:    300,
	})

	data, err := os.ReadFile("/Users/peytonmontei/Documents/entire/devenv/entireio/cli/.worktrees/redact/cmd/entire/cli/transcript/compact/testdata/claude_full2.jsonl")
	if err != nil {
		fmt.Fprintf(os.Stderr, "read fixture: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("input size: %d bytes\n", len(data))

	start := time.Now()
	out, err := redact.JSONLBytesWithPrivacyFilter(context.Background(), data)
	elapsed := time.Since(start)
	if err != nil {
		fmt.Fprintf(os.Stderr, "redact: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("elapsed: %v\n", elapsed)
	fmt.Printf("output size: %d bytes\n", out.Len())

	// Count REDACTED_PERSON tokens in output to confirm OPF actually did something.
	outStr := string(out.Bytes())
	count := 0
	idx := 0
	for {
		i := indexFrom(outStr, "REDACTED_PERSON", idx)
		if i < 0 {
			break
		}
		count++
		idx = i + len("REDACTED_PERSON")
	}
	fmt.Printf("REDACTED_PERSON tokens in output: %d\n", count)
}

func indexFrom(s, sub string, from int) int {
	if from >= len(s) {
		return -1
	}
	off := from
	for off+len(sub) <= len(s) {
		if s[off:off+len(sub)] == sub {
			return off
		}
		off++
	}
	return -1
}

