// RedactBatch sends multiple inputs to opf in a single invocation. opf
// treats each line of stdin as a separate input and emits one JSON object
// per input on stdout. We send `inputs` joined by '\n', then decode the
// concatenated JSON stream back into one []Span per input.
//
// Embedded newlines inside an input would otherwise cause opf to split
// that single logical input across multiple outputs. To preserve the
// 1:1 mapping (and to keep byte offsets in spans usable against the
// caller's original strings), every '\n' inside each input is replaced
// with ' ' before sending. The substitution is byte-for-byte same length,
// so the returned offsets line up with the original strings.
func (s *shellOut) RedactBatch(ctx context.Context, inputs []string, categories []string) ([][]Span, error) {
	if len(inputs) == 0 || len(categories) == 0 {
		return nil, nil
	}
	timeout := time.Duration(s.timeoutSeconds) * time.Second
	callCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	// Flatten embedded newlines so opf treats each input as exactly one
	// logical text. Byte offsets remain valid against the originals because
	// '\n' and ' ' are both 1 byte.
	flat := make([]string, len(inputs))
	for i, in := range inputs {
		flat[i] = strings.ReplaceAll(in, "\n", " ")
	}
	batched := strings.Join(flat, "\n")

	// opf has no per-call category filter on the CLI — it returns every
	// category it can detect. detectOPF filters spans to cfg.Categories
	// post-call. categories is retained on the signature for future
	// implementations (daemon mode, fine-tuned models) that may accept
	// category hints. --no-print-color-coded-text suppresses the
	// human-oriented summary + color preview that surround the JSON.
	args := []string{
		"--device", "cpu",
		"--output-mode", "typed",
		"--format", "json",
		"--no-print-color-coded-text",
	}

	cmd := s.CommandRunner(callCtx, s.command, args...)
	cmd.Stdin = strings.NewReader(batched)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		switch {
		case errors.Is(callCtx.Err(), context.DeadlineExceeded):
			return nil, fmt.Errorf("opf timeout after %s: %w", timeout, callCtx.Err())
		case errors.Is(ctx.Err(), context.Canceled):
			return nil, fmt.Errorf("opf canceled: %w", ctx.Err())
		}
		errMsg := strings.TrimSpace(stderr.String())
		if errMsg == "" {
			return nil, fmt.Errorf("opf exited with error: %w", err)
		}
		return nil, fmt.Errorf("opf exited with error: %s: %w", errMsg, err)
	}

	// opf emits multiple JSON objects back-to-back, one per input line.
	// Decode them in order; the Nth object's spans apply to inputs[N].
	dec := json.NewDecoder(bytes.NewReader(stdout.Bytes()))
	out := make([][]Span, 0, len(inputs))
	for dec.More() {
		var parsed opfOutput
		if err := dec.Decode(&parsed); err != nil {
			return nil, fmt.Errorf("opf output not parseable as JSON (decoded %d/%d so far): %w (stdout: %q)", len(out), len(inputs), err, stdout.String())
		}
		spans := make([]Span, 0, len(parsed.DetectedSpans))
		for _, p := range parsed.DetectedSpans {
			spans = append(spans, Span{Start: p.Start, End: p.End, Label: p.Label})
		}
		out = append(out, spans)
	}
	if len(out) != len(inputs) {
		return nil, fmt.Errorf("opf output count mismatch: got %d JSON objects, want %d (one per input)", len(out), len(inputs))
	}
	return out, nil
}

